{
  "$schema": "https://json.schemastore.org/claude-code-settings.json",
  "_comment": "Project-level hooks for EV Dashboard. See docs/writing_style.md and .claude/plans/this-project-was-being-gentle-adleman.md §1.8.",
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "FILE=$(jq -r '.tool_input.file_path // empty' <<< \"$CLAUDE_TOOL_INPUT\"); case \"$FILE\" in *.ts|*.tsx) cd \"$CLAUDE_PROJECT_DIR\" && npx tsc --noEmit --pretty false 2>&1 | head -20 || true ;; esac"
          },
          {
            "type": "command",
            "command": "FILE=$(jq -r '.tool_input.file_path // empty' <<< \"$CLAUDE_TOOL_INPUT\"); case \"$FILE\" in */src/data/seed.json) cd \"$CLAUDE_PROJECT_DIR\" && python3 scripts/validate.py || true ;; esac"
          },
          {
            "type": "command",
            "command": "FILE=$(jq -r '.tool_input.file_path // empty' <<< \"$CLAUDE_TOOL_INPUT\"); case \"$FILE\" in */src/lib/thermal.ts) cd \"$CLAUDE_PROJECT_DIR\" && npm test -- --run thermal 2>&1 | tail -10 || true ;; esac"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "CMD=$(jq -r '.tool_input.command // empty' <<< \"$CLAUDE_TOOL_INPUT\"); if echo \"$CMD\" | grep -qE 'rm -rf|git reset --hard|git push --force|git push -f|git branch -D'; then echo 'Blocked: destructive command requires explicit confirmation' >&2; exit 2; fi"
          },
          {
            "type": "command",
            "command": "CMD=$(jq -r '.tool_input.command // empty' <<< \"$CLAUDE_TOOL_INPUT\"); if echo \"$CMD\" | grep -qE '(^|[^/])(npx tsc|npm test|cargo test|cargo build)( |$)' && ! echo \"$CMD\" | grep -q 'scripts/quiet.py'; then echo '[quiet hint] wrap with: python3 scripts/quiet.py <cmd> (saves 70-95% of output tokens)' >&2; fi; if echo \"$CMD\" | grep -qE '(^|[^/])(git diff|git log)( |$)' && ! echo \"$CMD\" | grep -q 'scripts/quiet.py'; then echo '[quiet hint] git diff/log can be huge — consider: python3 scripts/quiet.py git ...' >&2; fi"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "cd \"$CLAUDE_PROJECT_DIR\" && if [ -f .queue_top3.md ]; then cat .queue_top3.md; else echo '(run: python3 scripts/queue.py)'; fi"
          }
        ]
      }
    ]
  }
}
